import{c as a,$ as r,Q as o,j as i,m as t,h as d,ax as s,n as c,o as l,S as p}from"./chunks/framework.DGHXLY8X.js";const _=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/introduction.md","filePath":"getting-started/introduction.md","lastUpdated":1780984191000}'),u={name:"getting-started/introduction.md"};function m(h,e,f,T,g,b){const n=r("Mermaid");return o(),i("div",null,[e[1]||(e[1]=t('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>This page explains what VideoNode is and how its three-entity pipeline model works. For step-by-step setup, see <a href="./installation">Installation</a> and <a href="./quickstart">Quickstart</a>.</p><p>VideoNode is a self-hosted video streaming server for Linux. It takes frames from V4L2 capture devices (webcams, HDMI capture cards) and publishes them as RTSP, SRT, and WebRTC streams. Because it runs headless and ships as a single binary plus native C++ pipeline binaries, it targets Rockchip RK3588 single-board computers (the FriendlyElec NanoPC-T6 is the reference board), and runs on any Linux host with a GPU through software fallbacks. The daemon detects connected devices automatically and builds FFmpeg pipelines from a declarative TOML config. Run the <code>validate-encoders</code> subcommand once to probe which hardware encoders work and record the result.</p><h2 id="three-entity-pipeline-model" tabindex="-1">Three-entity pipeline model <a class="header-anchor" href="#three-entity-pipeline-model" aria-label="Permalink to &quot;Three-entity pipeline model&quot;">​</a></h2><p>VideoNode organises every pipeline into three independent entities. Each has its own identity, CRUD surface, and lifecycle. Streams reference upstream entities by explicit ID. There is no monolithic block that bundles capture, composition, and encoding together.</p><ul><li><strong>Source</strong> captures V4L2 frames from one device (or generates a test pattern when <code>test_mode = true</code>) and broadcasts raw NV12 frames to any number of consumers. A source runs as a separate <code>videonode-source</code> process per source ID.</li><li><strong>Composer</strong> reads frames from one or more sources, composites them onto a canvas using libplacebo (Vulkan, with an OpenGL fallback), and broadcasts the result. Multiple streams can share one composer: the GPU does the compositing work once, and each stream pays only its own encoder cost. A composer is optional; streams that need no compositing reference a source directly.</li><li><strong>Stream</strong> pairs an upstream reference (<code>&quot;source:&lt;id&gt;&quot;</code> or <code>&quot;composer:&lt;id&gt;&quot;</code>) with an encoder config. The encoder publishes to the daemon&#39;s local RTSP relay, and SRT and WebRTC fan out from there; the output destination is hardcoded, not user-configurable. The encoder process spawns lazily when the first viewer connects and stops after the last one disconnects.</li></ul>',6)),(o(),d(p,null,{default:s(()=>[l(n,{id:"mermaid-33",class:"mermaid",graph:"flowchart%20TB%0A%20%20accTitle%3A%20VideoNode%20three-entity%20pipeline%20model%0A%20%20accDescr%20%7B%0A%20%20%20%20A%20V4L2%20device%20feeds%20videonode-source.%20The%20source%20broadcasts%20NV12%20frames%0A%20%20%20%20to%20videonode-composer%20and%20directly%20to%20videonode-sink%20instances%20via%0A%20%20%20%20SCM_RIGHTS.%20The%20composer%20produces%20a%20BGRA%20canvas%20that%20feeds%20its%20own%20sink.%0A%20%20%20%20Each%20sink%20pipes%20into%20ffmpeg%2C%20which%20publishes%20to%20RTSP%2C%20SRT%2C%20or%20WebRTC.%0A%20%20%7D%0A%0A%20%20dev%5B%22V4L2%20device%22%5D%20--%3E%20src%5B%22videonode-source%22%5D%0A%20%20src%20--%20%22NV12%22%20--%3E%20comp%5B%22videonode-composer%22%5D%0A%20%20src%20--%20%22NV12%22%20--%3E%20sink1%5B%22videonode-sink%22%5D%0A%20%20comp%20--%20%22BGRA%22%20--%3E%20sink2%5B%22videonode-sink%22%5D%0A%20%20sink1%20--%3E%20ff1%5B%22ffmpeg%22%5D%0A%20%20sink2%20--%3E%20ff2%5B%22ffmpeg%22%5D%0A%20%20ff1%20--%20%22H.264%2FH.265%22%20--%3E%20vn%5B%22videonode%20(RTSP%20%2F%20SRT%20%2F%20WebRTC%20fanout)%22%5D%0A%20%20ff2%20--%20%22H.264%2FH.265%22%20--%3E%20vn%0A%20%20vn%20--%3E%20viewers%5B%22viewers%22%5D%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>The config that drives this model uses three TOML tables: <code>[[sources]]</code>, <code>[[composers]]</code>, and <code>[[streams]]</code>. Each stream names its upstream with an <code>upstream</code> field; each composer lists its sources under <code>inputs[].ref</code>; sources carry no reference. For the full entity model and lifecycle details, see the <a href="./../reference/pipeline-model">pipeline model reference</a>.</p>',1))])}const A=a(u,[["render",m]]);export{_ as __pageData,A as default};
